// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(amount > 0);
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        vm.deal(caller, amount);
        vm.prank(caller);
        (bool deposited,) = address(c).call{value: amount}("");
        require(deposited, "deposit failed");

        uint256 balanceBefore = address(c).balance;
        uint256 userBalanceBefore = c.balances(caller);
        require(userBalanceBefore == amount, "deposit not recorded");

        vm.prank(caller);
        bool ok;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            uint256 balanceAfter = address(c).balance;
            uint256 userBalanceAfter = c.balances(caller);
            assertTrue(
                userBalanceAfter == 0 && balanceAfter <= balanceBefore - userBalanceBefore,
                "After successful withdraw: caller balance must be 0 and contract ETH must decrease by at least caller's prior balance"
            );
        }
    }
}
